export const tldrZh: Record<string, string> = {
  "egfr-mutant-nsclc": "EGFR突变型肺癌由单个异常的生长受体驱动，首选口服药物而非化疗。奥希替尼平均可将疾病控制约一年半，加用化疗或抗体埃万妥单抗可进一步延长，早期患者术后服用三年奥希替尼可使死亡风险大约减半。",
  "alk-positive-nsclc": "ALK阳性肺癌由融合的ALK基因驱动，从一开始就用口服药治疗。最新的抑制剂可将疾病控制数年，洛拉替尼使六成患者在五年时仍未进展，术后两年阿来替尼可将复发风险降低四分之三。",
  "kras-g12c-nsclc": "KRAS G12C肺癌携带一个四十年来被认为无法成药的突变。索托拉西布和阿达格拉西布如今可使化疗和免疫治疗后约四成的肿瘤缩小，尽管获益以月计，更新的抑制剂和一线联合免疫治疗正在试验中。",
  "ros1-positive-nsclc": "ROS1阳性肺癌是一种罕见的融合基因驱动的腺癌，用口服药治疗。克唑替尼是第一个，更新的瑞普替尼和他雷替尼可将疾病控制约三年，能进入大脑，并对使旧药失效的耐药突变有效。",
  "met-altered-nsclc": "MET驱动的肺癌有三种形式：用口服药卡马替尼或特泊替尼治疗的外显子14跳跃突变，常作为EGFR药物逃逸途径出现的MET扩增，以及抗体偶联药物telisotuzumab vedotin所针对的c-Met蛋白高表达。",
  "ret-fusion-nsclc": "RET融合肺癌是一种由融合RET基因驱动的罕见腺癌。选择性口服药塞普替尼可使大多数肿瘤缩小，与化疗加免疫治疗相比使进展时间延长一倍以上，普拉替尼是第二个选择。",
  "braf-v600e-nsclc": "BRAF V600E肺癌携带与许多黑色素瘤相同的突变，用同样的同时阻断BRAF和MEK的两药组合治疗。达拉非尼联合曲美替尼以及康奈非尼联合贝美替尼各可使约三分之二到四分之三的未治疗肿瘤缩小。",
  "her2-mutant-nsclc": "HER2突变型肺癌的受体与驱动HER2阳性乳腺癌的相同，但单用乳腺癌抗体在这里作用甚微。抗体偶联药物德曲妥珠单抗可使化疗后约一半的肿瘤缩小，口服药宗格替尼（zongertinib）约七成，两者均已获批。",
  "ntrk-fusion-nsclc": "NTRK融合肺癌非常罕见，用获批用于任何携带该融合的癌症的TRK阻断口服药治疗：拉罗替尼、恩曲替尼或瑞普替尼可使大多数肿瘤缩小，包括脑内病灶，因此关键是检测范围足够广以发现它。",
  "pdl1-high-nsclc": "携带大量PD-L1且没有可靶向突变的肺癌可以单用免疫治疗抗体而不用化疗。帕博利珠单抗使约三分之一的患者在五年时仍存活，大约是化疗的两倍，加用化疗留给需要快速起效的患者。",
  "resectable-nsclc": "在扩散前发现的肺癌用手术治疗，如今常为微创或机器人手术，有时只切除肺叶的一部分。手术前后给予免疫治疗，或EGFR或ALK肿瘤术后服用靶向药，可将复发几率降低三分之一到五分之四。",
  "stage-iii-unresectable-nsclc": "无法切除的III期肺癌以治愈为目标，同时进行化疗和放疗。之后一年的免疫治疗抗体度伐利尤单抗使五年生存率从三分之一提高到四成以上，EGFR突变肿瘤在放化疗后服用奥希替尼可将疾病控制数年。",
  "limited-stage-sclc": "仍局限于一侧胸腔的小细胞肺癌以治愈为目标，同时进行化疗和放疗。之后加用两年的免疫治疗抗体度伐利尤单抗使中位生存期从不到三年延长到四年半以上，这是该疾病数十年来的首次进步。",
  "extensive-stage-sclc": "已扩散的小细胞肺癌对化疗反应迅速，但几乎总在一年内复发。在一线化疗中加入免疫治疗抗体可使少数患者存活数年，将免疫细胞导向癌细胞DLL3蛋白的T细胞衔接器塔拉妥单抗首次延长了复发后的生命。",
  "flaura": "FLAURA显示，一开始就使用第三代EGFR药物奥希替尼而非留待以后，可使肺癌控制时间几乎翻倍，并帮助患者活得更久。",
  "alex": "ALEX显示，能进入大脑的第二代ALK药物阿来替尼可将ALK阳性肺癌控制约三年，而克唑替尼不到一年，并将脑进展减少四分之三。",
  "alta-1l": "ALTA-1L显示，与克唑替尼相比，布格替尼使ALK阳性肺癌的控制时间延长一倍以上，对脑转移有很强的活性。",
  "keynote-042": "KEYNOTE-042将单用帕博利珠单抗扩展到PD-L1至少1%的任何肺癌，但生存获益几乎全部来自50%以上的肿瘤，因此其余患者仍需加用化疗。",
  "empower-lung-1": "EMPOWER-Lung 1显示，第三种PD-1抗体西米普利单抗在高PD-L1肺癌中比化疗更能延长生命，用不同的药物重现了帕博利珠单抗的结果。",
  "geometry-mono-1": "GEOMETRY mono-1显示，卡马替尼可使三分之二携带MET外显子14跳跃突变的未治疗肺癌缩小，化疗后约四成缩小，使MET外显子14成为第七个拥有获批靶向药的肺癌驱动基因。",
  "pharos": "PHAROS显示，黑色素瘤组合康奈非尼联合贝美替尼可使四分之三的未治疗BRAF V600E肺癌和近一半经治肿瘤缩小，为肺癌提供了第二个获批的BRAF加MEK组合。",
  "destiny-lung02": "DESTINY-Lung02证实，抗体偶联药物德曲妥珠单抗可使约一半化疗后的HER2突变肺癌缩小，且较低剂量同样有效而肺部炎症更少。",
  "beamion-lung-1": "Beamion LUNG-1显示，阻断突变HER2而不影响EGFR的口服药宗格替尼（zongertinib）可使约七成化疗后的HER2突变肺癌缩小，它成为第一个获批用于肺癌的口服HER2药物。",
  "calgb-140503": "CALGB 140503显示，对于小的周围型肺癌，只切除肺叶的一部分与切除整个肺叶效果相同，因此筛查发现的肿瘤可以在切除更少肺组织的情况下治愈。",
};
